-- Section 1632: Reading Passage 2: Climate change reveals ancient artefacts in Norway&rsquo;s glaciers
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1632, 163, 'reading', 'Reading Passage 2: Climate change reveals ancient artefacts in Norway&rsquo;s glaciers', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-19                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>The Reading Passage has eight sections, <strong>A-H.</strong></p>
<p>Which section contains the following information?</p>
<p><em>Write the correct number, <strong>A-H</strong>, in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                                <table class="ielts-reading-matching-table"><thead><tr><th></th><th>A</th><th>B</th><th>C</th><th>D</th><th>E</th><th>F</th><th>G</th><th>H</th></tr></thead><tbody><tr class="ielts-reading-question-item"><td class="ielts-reading-matching-question-cell"><strong id="ielts-reading-question-number-14" class="ielts-q-badge">14</strong> <span>an explanation for weapons being left behind in the mountains</span></td>
