-- Section 1642: Reading Passage 2: Changes in reading habits
INSERT INTO sections (id, test_id, type, title, instructions, audio_url, passage_text, order_index) VALUES
(1642, 164, 'reading', 'Reading Passage 2: Changes in reading habits', '<div class="ielts-reading-container"><h2 class="ielts-reading-question-section-heading">
                                            Questions 14-17                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <p>Choose the correct letter, <strong>A</strong>, <strong>B</strong>, <strong>C</strong> or <strong>D</strong>.</p>
<p><em>Write the correct letter in boxes on your answer sheet.</em></p>
                                        </div>
                                        <div class="ielts-reading-questions">
                                                                                                                                                                                            <div class="ielts-standalone-q" data-qnum="14"><div class="ielts-q-header"><strong class="ielts-q-badge">14</strong><span class="ielts-q-title"><span>What is the writer’s main point in the first paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="A"><span class="ielts-radio-text"><strong>A</strong> Our use of technology is having a hidden effect on us.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="B"><span class="ielts-radio-text"><strong>B</strong> Technology can be used to help youngsters to read.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="C"><span class="ielts-radio-text"><strong>C</strong> Travellers should be encouraged to use technology on planes.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="14" name="question_14" value="D"><span class="ielts-radio-text"><strong>D</strong> Playing games is a more popular use of technology than reading.</span></label></div></div><div class="ielts-standalone-q" data-qnum="15"><div class="ielts-q-header"><strong class="ielts-q-badge">15</strong><span class="ielts-q-title"><span>What main point does Sherry Turkle make about innovation?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="A"><span class="ielts-radio-text"><strong>A</strong> Technological innovation has led to a reduction in print reading.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="B"><span class="ielts-radio-text"><strong>B</strong> We should pay attention to what might be lost when innovation occurs.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="C"><span class="ielts-radio-text"><strong>C</strong> We should encourage more young people to become involved in innovation.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="15" name="question_15" value="D"><span class="ielts-radio-text"><strong>D</strong> There is a difference between developing products and developing ideas.</span></label></div></div><div class="ielts-standalone-q" data-qnum="16"><div class="ielts-q-header"><strong class="ielts-q-badge">16</strong><span class="ielts-q-title"><span>What point is the writer making in the fourth paragraph?</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="A"><span class="ielts-radio-text"><strong>A</strong> Humans have an inborn ability to read and write.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="B"><span class="ielts-radio-text"><strong>B</strong> Reading can be done using many different mediums.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="C"><span class="ielts-radio-text"><strong>C</strong> Writing systems make unexpected demands on the brain.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="16" name="question_16" value="D"><span class="ielts-radio-text"><strong>D</strong> Some brain circuits adjust to whatever is required of them.</span></label></div></div><div class="ielts-standalone-q" data-qnum="17"><div class="ielts-q-header"><strong class="ielts-q-badge">17</strong><span class="ielts-q-title"><span>According to Mark Edmundson, the attitude of college students</span></div><div class="ielts-radio-group"><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="A"><span class="ielts-radio-text"><strong>A</strong> has changed the way he teaches.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="B"><span class="ielts-radio-text"><strong>B</strong> has influenced what they select to read.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="C"><span class="ielts-radio-text"><strong>C</strong> does not worry him as much as it does others.</span></label><label class="ielts-radio-btn"><input type="radio" data-qnum="17" name="question_17" value="D"><span class="ielts-radio-text"><strong>D</strong> does not match the views of the general public.</span></label></div></div></div>
                                                                                                                                    </div>
                                                                                                                                                            <h2 class="ielts-reading-question-section-heading">
                                            Questions 18-22                                                                                                                                                
                                                                                                                                    </h2>
                                        <div class="ielts-reading-question-section-content">
                                            <div class="ielts-reading-section-content-wrapper"><p>Complete the summary using the list of words, <strong>A-H</strong>, below.</p>
<p><em>Write the correct letter, <strong>A-H</strong>, in boxes on your answer sheet.</em></p>
<p class="ielts-reading-passage-subhead"><strong><strong>Studies on digital screen use</strong></strong></p>
<p>There have been many studies on digital screen use, showing some <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">18</strong><select data-qnum="18" name="question_18" class="ielts-inline-select"><option value="">[ 18 ] Tanlang...</option><option value="A. fast">A. fast</option><option value="B. isolated">B. isolated</option><option value="C. emotional">C. emotional</option><option value="D. worrying">D. worrying</option><option value="E. many">E. many</option><option value="F. hard">F. hard</option><option value="G. combined">G. combined</option><option value="H. thorough">H. thorough</option></select></span></span> trends. Psychologist Anne Mangen gave high-school students a short story to read, half using digital and half using print mediums. Her team then used a question-and-answer technique to find out how <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">19</strong><select data-qnum="19" name="question_19" class="ielts-inline-select"><option value="">[ 19 ] Tanlang...</option><option value="A. fast">A. fast</option><option value="B. isolated">B. isolated</option><option value="C. emotional">C. emotional</option><option value="D. worrying">D. worrying</option><option value="E. many">E. many</option><option value="F. hard">F. hard</option><option value="G. combined">G. combined</option><option value="H. thorough">H. thorough</option></select></span></span> each group’s understanding of the plot was. The findings showed a clear pattern in the responses, with those who read screens finding the order of information <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">20</strong><select data-qnum="20" name="question_20" class="ielts-inline-select"><option value="">[ 20 ] Tanlang...</option><option value="A. fast">A. fast</option><option value="B. isolated">B. isolated</option><option value="C. emotional">C. emotional</option><option value="D. worrying">D. worrying</option><option value="E. many">E. many</option><option value="F. hard">F. hard</option><option value="G. combined">G. combined</option><option value="H. thorough">H. thorough</option></select></span></span> to recall.</p>
<p>Studies by Ziming Liu show that students are tending to read <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">21</strong><select data-qnum="21" name="question_21" class="ielts-inline-select"><option value="">[ 21 ] Tanlang...</option><option value="A. fast">A. fast</option><option value="B. isolated">B. isolated</option><option value="C. emotional">C. emotional</option><option value="D. worrying">D. worrying</option><option value="E. many">E. many</option><option value="F. hard">F. hard</option><option value="G. combined">G. combined</option><option value="H. thorough">H. thorough</option></select></span></span> words and phrases in a text to save time. This approach, she says, gives the reader a superficial understanding of the <span class="ielts-reading-question-item"><span class="ielts-inline-select-wrap"><strong class="ielts-q-badge">22</strong><select data-qnum="22" name="question_22" class="ielts-inline-select"><option value="">[ 22 ] Tanlang...</option><option value="A. fast">A. fast</option><option value="B. isolated">B. isolated</option><option value="C. emotional">C. emotional</option><option value="D. worrying">D. worrying</option><option value="E. many">E. many</option><option value="F. hard">F. hard</option><option value="G. combined">G. combined</option><option value="H. thorough">H. thorough</option></select></span></span> content of material, leaving no time for thought.</p>
